(() => {
const menu=document.createElement('button');menu.className='mobile-menu-toggle';menu.type='button';menu.innerHTML='<span aria-hidden="true">☰</span> Menu';menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-controls','mobile-site-menu');document.querySelector('.left').id='mobile-site-menu';document.querySelector('.topbar').append(menu);
const backdrop=document.createElement('div');backdrop.className='mobile-menu-backdrop';backdrop.hidden=true;document.body.append(backdrop);
function setMenu(open){document.body.classList.toggle('mobile-menu-open',open);backdrop.hidden=!open;menu.setAttribute('aria-expanded',String(open));menu.innerHTML=open?'<span aria-hidden="true">×</span> Fechar':'<span aria-hidden="true">☰</span> Menu';}
backdrop.addEventListener('click',()=>setMenu(false));document.addEventListener('keydown',e=>{if(e.key!=='Tab'||!document.body.classList.contains('mobile-menu-open'))return;const nodes=[menu,...document.querySelectorAll('.left a,.left button,.left select')].filter(n=>n.getClientRects().length);if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();menu.focus();}});
menu.addEventListener('click',()=>setMenu(!document.body.classList.contains('mobile-menu-open')));document.addEventListener('keydown',e=>{if(e.key==='Escape')setMenu(false);});document.querySelector('.left').addEventListener('click',e=>{if(e.target.closest('a'))setMenu(false);});window.addEventListener('hashchange',()=>{setMenu(false);enhance();requestAnimationFrame(()=>window.scrollTo({top:0,behavior:'instant'}));});matchMedia('(min-width: 701px)').addEventListener('change',e=>{if(e.matches)setMenu(false);});
const dialog=document.querySelector('#detail');dialog.setAttribute('aria-label','Detalhes do registro');document.querySelector('#close').setAttribute('aria-label','Fechar detalhes');
function enhance(){if(location.hash==='#acervo/hall-of-fame'){const header=document.querySelector('.reader-header p');if(header)header.textContent=players.length+' jogadores · Ordenados por títulos conquistados';const count=document.querySelector('.reader-tools>span');if(count)count.textContent=players.length+' JOGADORES';const label=document.querySelector('.reader-tools label');if(label&&label.firstChild.nodeType===3)label.firstChild.textContent='Ir para jogador';}document.querySelectorAll('.awards-table:not(.annual-ranking-table)').forEach(table=>{const labels=[...table.querySelectorAll('thead th')].map(th=>th.textContent);table.querySelectorAll('tbody tr').forEach(tr=>[...tr.children].forEach((td,i)=>td.dataset.label=labels[i]||''));});}
document.addEventListener('input',enhance);document.addEventListener('change',enhance);document.addEventListener('click',()=>queueMicrotask(enhance));enhance();
const top=document.createElement('button');top.className='back-to-top';top.type='button';top.textContent='↑';top.setAttribute('aria-label','Voltar ao topo');top.hidden=true;document.body.append(top);window.addEventListener('scroll',()=>{top.hidden=scrollY<600;},{passive:true});top.addEventListener('click',()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));
})();
